#!/usr/bin/env python3
"""Scan the complete compatibility cube generated by rank-3's legal 1-swaps.

The rank-3 parent has ten exact 1-for-1 replacements.  Earlier exhaustive
3-swap and 4-swap searches show 80 legal states at each depth.  This script
combines all ten primitive moves in every compatible subset, so it tests the
entire subspace generated by those moves at once (all depths 0..10), rather
than extending the swap radius one level at a time.
"""

import argparse
import json
from collections import defaultdict
from pathlib import Path

import generalized9 as g
import neutral2_maxsat as nm
import rank3_square_relax as rs
import rank3_x294_two_swap_matching as tw

SPECIAL = 294
BASELINE = 134753


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("r367", type=Path)
    ap.add_argument("baseline", type=Path)
    ap.add_argument("output", type=Path)
    ap.add_argument("status", type=Path)
    args = ap.parse_args()

    digits = tuple(g.dec5(v) for v in range(g.U))
    r0 = g.load_r(args.r367)
    xset = g.make_x(r0, digits)
    r = rs.load_rank3_state(r0, digits)
    rsup, _ = g.support_masks(r, digits)

    base_model, bst = nm.solve_maxsat(rs.RANK3_K9, r, xset, digits, rsup)
    if base_model is None or bst["score"] != BASELINE:
        raise RuntimeError(f"base drift {bst}")
    _, hs, vs = base_model

    x0 = xset[SPECIAL]
    weights = [sum(1 for f in arr if g.conflict(x0, f, digits)) for arr in vs]
    positive = [j for j, c in enumerate(weights) if c]
    if len(positive) != 366 or any(weights[j] != 1 for j in positive):
        raise RuntimeError("weight drift")
    ridx = {j: k for k, j in enumerate(positive)}
    adj_all = [[] for _ in range(g.U)]
    for j in positive:
        k = ridx[j]
        for v in rs.neighborhood(xset[j], digits):
            adj_all[v].append(k)

    # Exact primitive 1-swaps are precisely outside points with singleton
    # conflict support against the rank-3 parent.
    moves = []
    for v, sm in enumerate(rsup):
        if v in set(r):
            continue
        if sm.bit_count() == 1:
            owner = (sm & -sm).bit_length() - 1
            moves.append((owner, v))
    moves.sort()
    if len(moves) != 10 or len({o for o, _ in moves}) != 10:
        raise RuntimeError(f"primitive move drift: {moves}")

    # A subset is legal iff all replacement endpoints are pairwise separated;
    # each endpoint only conflicts with its own removed owner among old points.
    bad = [0] * len(moves)
    for i, (_, a) in enumerate(moves):
        for j in range(i + 1, len(moves)):
            b = moves[j][1]
            if g.conflict(a, b, digits):
                bad[i] |= 1 << j
                bad[j] |= 1 << i

    base_m = tw.hk([adj_all[v] for v in r], 366)
    if base_m != 366:
        raise RuntimeError(f"base matching {base_m}")

    valid_by_size = defaultdict(int)
    match_hist_by_size = defaultdict(lambda: defaultdict(int))
    best_m = base_m
    best = []
    checked = 0

    for mask in range(1 << len(moves)):
        legal = True
        mm = mask
        while mm:
            bit = mm & -mm
            i = bit.bit_length() - 1
            if bad[i] & mask:
                legal = False
                break
            mm ^= bit
        if not legal:
            continue

        G = list(r)
        selected = []
        for i, (owner, v) in enumerate(moves):
            if mask >> i & 1:
                G[owner] = v
                selected.append(i)
        if len(set(G)) != 367:
            raise RuntimeError("duplicate cube state")

        k = len(selected)
        valid_by_size[k] += 1
        m = tw.hk([adj_all[z] for z in G], 366)
        checked += 1
        match_hist_by_size[k][m] += 1
        rec = (mask, tuple(selected), G)
        if m < best_m:
            best_m = m
            best = [rec]
        elif m == best_m and len(best) < 100:
            best.append(rec)

    # Independent cross-check against the already-exhaustive depth-3 and
    # depth-4 enumerators.  Equality means those exact spaces are fully inside
    # this primitive-move cube, not merely sampled by it.
    if valid_by_size[3] != 80 or valid_by_size[4] != 80:
        raise RuntimeError(
            f"cube cross-check drift: depth3={valid_by_size[3]} depth4={valid_by_size[4]}"
        )

    status = {
        "candidate": False,
        "method": "rank3-x294-full-primitive-move-cube",
        "primitive_moves": [
            {"owner": o, "old": r[o], "new": v} for o, v in moves
        ],
        "states_checked": checked,
        "legal_states_by_swap_count": {str(k): valid_by_size[k] for k in sorted(valid_by_size)},
        "matching_histogram_by_swap_count": {
            str(k): {str(m): n for m, n in sorted(h.items())}
            for k, h in sorted(match_hist_by_size.items())
        },
        "base_matching": base_m,
        "min_matching": best_m,
        "max_closure_objective": 367 - best_m,
        "best_masks": [z[0] for z in best],
        "base_maxsat": bst,
    }

    if best_m <= 365:
        mask, selected, G = best[0]
        bidx = [i for i in range(367) if i not in set(rs.RANK3_K9)]
        baseids = {int(p, 7) for p in json.loads(args.baseline.read_text())["points"]}
        obj, cert, nsel, pen, cost, rm, ad = tw.closure(
            G, weights, xset, digits, hs, vs, r, bidx, baseids
        )
        score = BASELINE + (obj - len(hs[SPECIAL]))
        if len(cert) != score or score <= BASELINE:
            raise RuntimeError(f"closure replay score={score} cert={len(cert)} obj={obj}")
        status.update({
            "candidate": True,
            "score": score,
            "winning_mask": mask,
            "winning_moves": [
                {"owner": moves[i][0], "old": r[moves[i][0]], "new": moves[i][1]}
                for i in selected
            ],
            "closure_objective": obj,
            "selected_endpoints": nsel,
            "penalty_old_v_ports": pen,
            "rc2_cost": cost,
            "removed_vs_baseline": rm,
            "added_vs_baseline": ad,
        })
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(
            json.dumps({"points": [g.dec10(z) for z in sorted(cert)]}, separators=(",", ":")) + "\n"
        )

    args.status.parent.mkdir(parents=True, exist_ok=True)
    args.status.write_text(json.dumps(status, indent=2, sort_keys=True) + "\n")
    print(("FOUND" if status["candidate"] else "NONE"), json.dumps(status, sort_keys=True), flush=True)


if __name__ == "__main__":
    main()
